const escape = (value) => String(value ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const number = (value) => new Intl.NumberFormat('it-IT', { maximumFractionDigits: 2 }).format(value);
export const studio = { tab: 'text', draft: 'Guscio 120 × 80 × 35 mm, spessore 2 mm, raggio 8 mm, ABS lucido', proposal: null, previous: null, imported: null, source: 'parametric', photo: null, photoName: '', message: '', busy: false };

export function renderWorkspace({ project, wall, properties, exploded, transparent }) {
  const imported = studio.source === 'imported';
  return `<section class="cad-workspace card" aria-label="Workspace di modellazione">
    <div class="cad-toolbar"><div class="workspace-title"><span class="live-dot"></span><strong>Design studio</strong><span class="version-tag">PROTOTIPO 02</span></div><div class="workspace-tools"><button class="button secondary compact" data-view="summary">Requisiti</button><button class="button primary compact" data-view="part">Prepara il progetto →</button></div></div>
    <div class="cad-grid">
      <aside class="model-browser"><div class="panel-heading">ESPLORA PROGETTO <span>01</span></div><div class="assembly-name">◇ Involucro elettronica</div><button class="tree-item ${!imported ? 'selected' : ''}" data-model-source="parametric"><span>▧</span><span>Gusci parametrici<small>Geometria modificabile</small></span><span class="tree-status">2</span></button><div class="tree-children"><span>⌑ Guscio anteriore</span><span>⌑ Guscio posteriore</span></div>${studio.imported ? `<button class="tree-item ${imported ? 'selected' : ''}" data-model-source="imported"><span>◇</span><span>${escape(studio.imported.file_name)}<small>Mesh · solo questa sessione</small></span></button>` : ''}<div class="browser-divider"></div><div class="panel-heading">DATI DI PROGETTO</div><button class="tree-link" data-view="brief">▤ Richiesta cliente <span>↗</span></button><button class="tree-link" data-view="part">◈ Materiali e vincoli <span>↗</span></button><button class="tree-link" data-view="machines">▱ Parco presse <span>↗</span></button><div class="browser-divider"></div><div class="panel-heading">PERCORSO DI SVILUPPO</div><ol class="design-path"><li class="current"><span>1</span><div>Geometria del pezzo<small>Fase attuale</small></div></li><li><span>2</span><div>Analisi di stampabilità<small>Modulo da sviluppare</small></div></li><li><span>3</span><div>Stampo, pressa e costi<small>Modulo da sviluppare</small></div></li><li><span>4</span><div>Simulazione e processo<small>Modulo da sviluppare</small></div></li></ol><div class="browser-note">Ogni fase partirà da geometria, requisiti e ipotesi tracciabili.</div></aside>
      <div class="model-stage"><div class="stage-top"><span class="stage-name">${imported ? 'MESH IMPORTATA' : 'ASSIEME PARAMETRICO'} <span>· mm</span></span><span class="stage-state">${imported ? 'Unità confermate · superficie da verificare' : 'Geometria preliminare'}</span></div><div class="viewport-wrap"><div class="viewport-actions"><div class="view-buttons">${[['iso', 'ISO'], ['front', 'Fronte'], ['rear', 'Retro'], ['side', 'Lato']].map(([view, label]) => `<button class="button secondary compact" data-concept-camera="${view}">${label}</button>`).join('')}</div><div class="view-buttons"><button class="button secondary compact" id="concept-explode" aria-pressed="${exploded}" ${imported ? 'disabled' : ''}>Esploso</button><button class="button secondary compact" id="concept-transparent" aria-pressed="${transparent}">Trasparenza</button></div></div><div class="concept-viewport" id="concept-viewport"><p class="concept-loading">Preparazione modello…</p></div><div class="viewport-label"><span class="axis-label"><i>X</i><i>Y</i><i>Z</i></span><span>Trascina per orbitare · scorri per ingrandire</span></div></div><div class="stage-bottom"><div class="preview-variants"><span>PARETE <small>Confronto preliminare</small></span><div>${project.part.wall_options_mm.map((value) => `<button class="button secondary compact ${value === wall ? 'selected' : ''}" data-preview-wall="${value}" aria-pressed="${value === wall}" ${imported ? 'disabled' : ''}>${number(value)} mm</button>`).join('')}</div></div><div class="concept-metrics" id="concept-metrics"></div></div><div class="stage-footer"><span>${imported ? 'Mesh in memoria · ricaricare il file dopo il riavvio' : 'Agganci, tenute e dettagli funzionali da modellare'}</span><button class="button secondary compact" id="concept-download" disabled>↓ Esporta OBJ</button></div></div>
      <aside class="creation-panel"><div class="panel-heading">CREA IL TUO PEZZO <span>↗</span></div><h2>Parti da un’idea.</h2><p class="panel-intro">Descrivi un guscio, apri un modello o aggiungi un riferimento.</p><div class="source-tabs" role="tablist" aria-label="Origine del pezzo">${[['text', 'Descrivi'], ['file', 'File 3D'], ['photo', 'Foto']].map(([key, label]) => `<button id="source-tab-${key}" role="tab" aria-selected="${studio.tab === key}" aria-controls="source-panel-${key}" data-source-tab="${key}" tabindex="${studio.tab === key ? 0 : -1}">${label}</button>`).join('')}</div>
      <section class="source-panel" id="source-panel-text" role="tabpanel" aria-labelledby="source-tab-text" ${studio.tab !== 'text' ? 'hidden' : ''}><div class="local-label">COMANDI PARAMETRICI LOCALI</div><form id="description-form"><label for="part-description">Che cosa vuoi creare?</label><textarea id="part-description" maxlength="4000" placeholder="Guscio 140 × 90 × 40 mm, spessore 2 mm, raggio 10 mm, ABS…">${escape(studio.draft)}</textarea><p class="source-help">In questa demo riconosco quote, spessore, raggio, ABS/PC-ABS/PP/PE e finitura. L’agente conversazionale è il prossimo passo.</p><button class="button primary" type="submit">Prepara modifica <span>↗</span></button></form><div id="description-proposal" aria-live="polite"></div><button class="text-button undo-command" id="undo-description" ${studio.previous ? '' : 'hidden'}>↶ Annulla ultima modifica da testo</button></section>
      <section class="source-panel" id="source-panel-file" role="tabpanel" aria-labelledby="source-tab-file" ${studio.tab !== 'file' ? 'hidden' : ''}><label for="mesh-units">Unità delle coordinate del file</label><select id="mesh-units"><option value="">Seleziona unità</option><option value="mm">Millimetri</option><option value="cm">Centimetri</option><option value="m">Metri</option><option value="in">Pollici</option></select><label class="upload-zone" for="mesh-file"><span>◇</span><strong>Apri un modello 3D</strong><small>OBJ / STL · max 12 MB · 100.000 triangoli</small><input id="mesh-file" type="file" accept=".obj,.stl"></label><p class="source-help">Visualizzazione e ingombri della mesh, senza modificare il brief. STEP e solidi CAD richiedono il prossimo modulo Open CASCADE.</p>${studio.imported ? `<div class="asset-info">${escape(studio.imported.file_name)}<small>${number(studio.imported.triangle_count)} triangoli · origine ${escape(studio.imported.source_units)}</small></div><button class="text-button" id="adopt-mesh-dimensions">Usa questi ingombri nel brief</button>` : ''}</section>
      <section class="source-panel" id="source-panel-photo" role="tabpanel" aria-labelledby="source-tab-photo" ${studio.tab !== 'photo' ? 'hidden' : ''}><label class="upload-zone" for="photo-file"><span>▣</span><strong>Aggiungi una foto</strong><small>JPG / PNG / WebP · max 8 MB</small><input id="photo-file" type="file" accept="image/jpeg,image/png,image/webp"></label>${studio.photo ? `<figure class="photo-reference"><img src="${escape(studio.photo)}" alt="Fotografia di riferimento caricata dall’utente"><figcaption>${escape(studio.photoName)} · solo questa sessione</figcaption></figure><button class="text-button" id="remove-photo">Rimuovi riferimento</button>` : ''}<p class="source-help">La foto resta un riferimento visivo. Per ricostruire il pezzo servono almeno una quota nota e più viste; interni, tolleranze e materiale vanno specificati.</p><div class="feature-note">Ricostruzione automatica da immagini: modulo da sviluppare.</div></section>
      <p class="studio-message" id="studio-message" role="status">${escape(studio.message)}</p><details class="properties-section" ${studio.tab === 'properties' ? 'open' : ''}><summary>Proprietà del guscio parametrico <span>⌄</span></summary><div class="compact-properties">${properties}</div></details><div class="next-operation"><div class="local-label">DOPO LA GEOMETRIA</div><strong>Prepara la stampabilità</strong><p>Definisci grado materiale, requisiti e superfici prima del concept stampo.</p><button class="text-button" data-view="part">Apri requisiti tecnici →</button></div></aside>
    </div><div class="cad-status"><span><span class="live-dot"></span> Elaborazione locale</span><span>${imported ? 'Mesh importata' : 'Modello parametrico'} <span class="status-separator">/</span> Nessuna validazione tecnica eseguita</span><span>mm <span class="status-separator">/</span> WebGL</span></div>
  </section>`;
}
